package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.OwnerHouseholdDuplicateException;

/**
 * Runs after {@link ValidateOwner} and before {@link BuildOwner}. Rejects the create with a 409 via
 * {@link OwnerHouseholdDuplicateException} when another owner already belongs to the same household
 * (same lastName and address — see {@link OwnerHousehold} for how that is compared).
 *
 * <p>The request may opt out of this rule by setting {@code sharesHousehold} true, which permits
 * creating a second owner in the same household; {@link AssignHousehold} then gives the new owner the
 * existing household's identifier.
 */
public class CheckOwnerHouseholdUnique {

    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
            throws OwnerHouseholdDuplicateException {
        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
            return; // opted in to sharing a household; skip the duplicate check
        }
        OwnerHousehold household = OwnerHousehold.of(request);
        for (Owner existing : ownerRepository.findAll()) {
            if (household.equals(OwnerHousehold.of(existing))) {
                throw new OwnerHouseholdDuplicateException(request.getLastName(), request.getAddress());
            }
        }
    }
}
===== OwnerTelephone =====
package org.springframework.samples.petclinic.rest.function.owner;

/**
 * Single source of truth for the "E.164 telephone" concept shared by the create pipeline:
 * {@link ValidateOwner} converts the submitted value to E.164 before storing it, and
 * {@link CheckOwnerTelephoneUnique} converts stored owner values the same way when comparing for
 * duplicates. Keeping the rule here ensures the value that gets stored and the value compared for
 * uniqueness can never silently diverge.
 */
public final class OwnerTelephone {

    private OwnerTelephone() {
    }

    /**
     * Convert a raw telephone to E.164 form, or return {@code null} if it cannot form a valid E.164
     * number. Spaces, dashes and brackets are stripped. A leading {@code '+'} keeps its country code;
     * otherwise country code {@code '+61'} is assumed and a single leading {@code '0'} is dropped from
     * the national digits. The result must have 8 to 15 digits after the {@code '+'}.
     *
     * <p>The national-number length is also checked against the country code: {@code '+61'} (Australia)
     * requires 9 national digits and {@code '+1'} (NANP) requires 10. A number whose national part is
     * the wrong length for its country code cannot form a valid E.164 number and returns {@code null}.
     */
    public static String toE164(String value) {
        if (value == null) {
            return null;
        }
        // Strip spaces, dashes and brackets (round and square).
        String cleaned = value.replaceAll("[\\s()\\[\\]-]", "");
        String digits;
        if (cleaned.startsWith("+")) {
            digits = cleaned.substring(1);
        }
        else {
            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
            digits = "61" + national;
        }
        if (!digits.matches("[0-9]{8,15}")) {
            return null;
        }
        if (!nationalLengthValid(digits)) {
            return null;
        }
        return "+" + digits;
    }

    /**
     * Check the national-number length for the known country codes. {@code '+61'} requires 9 national
     * digits and {@code '+1'} requires 10; other country codes are not length-checked here.
     */
    private static boolean nationalLengthValid(String digits) {
        if (digits.startsWith("61")) {
            return digits.length() - 2 == 9;
        }
        if (digits.startsWith("1")) {
            return digits.length() - 1 == 10;
        }
        return true;
    }
}
===== OwnerHousehold =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Locale;

import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;

/**
 * The identity of an owner's household: its {@code lastName} and {@code address} compared
 * case-insensitively, with surrounding whitespace stripped and internal runs collapsed to a single
 * space. The {@code address} is additionally run through the shared {@link OwnerAddress} normalization
 * (upper-casing and expanding abbreviations), so a stored normalized address and a raw one match.
 * Two owners belong to the same household when their {@code OwnerHousehold} values are equal.
 *
 * <p>This is the single definition of "same household" shared by {@link CheckOwnerHouseholdUnique}
 * (which iterates to reject a second owner joining a household) and {@link AssignHousehold} (which
 * iterates to find the donor owner whose {@code householdId} a new member inherits). Changing the
 * matching rule — e.g. trimming punctuation or including city — happens here, once.
 */
public record OwnerHousehold(String lastName, String address) {

    public OwnerHousehold {
        lastName = normalize(lastName);
        address = OwnerAddress.normalize(address);
    }

    public static OwnerHousehold of(Owner owner) {
        return new OwnerHousehold(owner.getLastName(), owner.getAddress());
    }

    public static OwnerHousehold of(OwnerFieldsDto fields) {
        return new OwnerHousehold(fields.getLastName(), fields.getAddress());
    }

    /** Lower-cases and collapses whitespace so comparison ignores case and incidental spacing. */
    private static String normalize(String value) {
        if (value == null) {
            return "";
        }
        return value.strip().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
    }
}
===== ValidateOwner =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.ArrayList;
import java.util.List;
import java.util.regex.Pattern;

import net.officefloor.plugin.variable.Out;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.OwnerEmailInvalidException;
import org.springframework.samples.petclinic.rest.escalation.OwnerFieldsMissingException;
import org.springframework.samples.petclinic.rest.escalation.OwnerTelephoneInvalidException;
import org.springframework.web.bind.annotation.RequestBody;

/**
 * First step of {@code POST /api/owners} and the single step that binds the request body. Rejects a
 * body that is missing or blank in any required field (firstName, lastName, address, city, telephone)
 * with a 400 whose {@code errors} array lists the offending field names. A whitespace-only value is
 * treated as blank — the DTO's {@code @Size(min = 1)} alone would accept it — so this check, not bean
 * validation, is the authoritative implementation of the required-field rule.
 *
 * <p>The address is normalized (see {@link OwnerAddress}) before the required-field check, so an
 * address that is blank once whitespace is collapsed is rejected as missing. The normalized value is
 * written back onto the body so the normalized, abbreviation-expanded address is what gets stored,
 * returned and compared for household matching.
 *
 * <p>The telephone is then converted to E.164 form (see {@link OwnerTelephone#toE164(String)}); a
 * value that cannot form a valid E.164 number is rejected with a 400 via
 * {@link OwnerTelephoneInvalidException}. The E.164 value is written back onto the body so it is what
 * gets stored and returned.
 *
 * <p>Email is optional. When absent (null) it is left untouched. When present it must be a
 * syntactically valid address; otherwise the create is rejected with a 400 via
 * {@link OwnerEmailInvalidException}. A valid email is lower-cased and written back onto the body so
 * the lower-cased value is what gets stored and returned. The validated body is republished for
 * {@link BuildOwner}.
 */
public class ValidateOwner {

    /** Pragmatic syntactic check: non-empty local part, '@', non-empty domain containing a dot. */
    private static final Pattern EMAIL = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");

    public void service(@RequestBody OwnerFieldsDto request, Out<OwnerFieldsDto> validated)
            throws OwnerFieldsMissingException, OwnerTelephoneInvalidException,
            OwnerEmailInvalidException {
        List<String> missing = new ArrayList<>();
        if (isBlank(request.getFirstName())) {
            missing.add("firstName");
        }
        if (isBlank(request.getLastName())) {
            missing.add("lastName");
        }
        String address = OwnerAddress.normalize(request.getAddress());
        if (address.isEmpty()) {
            missing.add("address");
        }
        if (isBlank(request.getCity())) {
            missing.add("city");
        }
        if (isBlank(request.getTelephone())) {
            missing.add("telephone");
        }
        if (!missing.isEmpty()) {
            throw new OwnerFieldsMissingException(missing);
        }
        request.setAddress(address);
        String e164 = OwnerTelephone.toE164(request.getTelephone());
        if (e164 == null) {
            throw new OwnerTelephoneInvalidException(request.getTelephone());
        }
        request.setTelephone(e164);

        String email = request.getEmail();
        if (email != null) {
            if (!EMAIL.matcher(email).matches()) {
                throw new OwnerEmailInvalidException(email);
            }
            request.setEmail(email.toLowerCase());
        }

        validated.set(request);
    }

    private static boolean isBlank(String value) {
        return value == null || value.isBlank();
    }
}
===== AssignHousehold =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.UUID;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;

/**
 * Runs after {@link BuildOwner} on {@code POST /api/owners} and assigns the new owner's stable
 * {@code householdId}.
 *
 * <p>When the request opted in via {@code sharesHousehold} true, the new owner joins an existing
 * household: the first already-persisted owner in the same household (see {@link OwnerHousehold})
 * donates its {@code householdId} so both owners share one identifier. Otherwise (not sharing, or
 * sharing with no existing household to join) a fresh random identifier is minted so every owner
 * always has a non-blank {@code householdId}.
 */
public class AssignHousehold {

    public void service(@Val Owner owner, @Val OwnerFieldsDto request, OwnerRepository ownerRepository) {
        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
            OwnerHousehold household = OwnerHousehold.of(owner);
            for (Owner existing : ownerRepository.findAll()) {
                if (existing.getHouseholdId() != null && household.equals(OwnerHousehold.of(existing))) {
                    owner.setHouseholdId(existing.getHouseholdId());
                    return;
                }
            }
        }
        owner.setHouseholdId(UUID.randomUUID().toString());
    }
}

