package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Locale;

import org.springframework.samples.petclinic.model.Owner;

/**
 * Single source of truth for an owner's {@code identityKey}: the one derived value all duplicate
 * detection on {@code POST /api/owners} is expressed through. The key is
 * {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}; two owners are the same
 * identity exactly when their whole keys are equal.
 *
 * <p>This deliberately folds the former separate telephone, email and household duplicate checks into
 * one comparison. Because the telephone is part of the key, two members of the same household (same
 * {@code householdId}) with different telephones have different keys and are both allowed — only an
 * exact full-key match is a duplicate (see {@link CheckOwnerIdentityUnique}).
 *
 * <p>The components are normalized the same way for a submitted owner and a stored one, so values
 * with incidental telephone formatting or email casing still match: the telephone is run through
 * {@link OwnerTelephone#toE164(String)} and the email is lower-cased. A {@code null} component
 * contributes the empty string.
 */
public final class OwnerIdentity {

    private OwnerIdentity() {
    }

    /** The {@code identityKey} of a persisted or in-flight owner, computed from its stored fields. */
    public static String of(Owner owner) {
        return keyOf(owner.getTelephone(), owner.getEmail(), owner.getHouseholdId());
    }

    /**
     * Build the {@code identityKey} from raw components, normalizing each the same way regardless of
     * source. The telephone is normalized to E.164 (falling back to the raw value when it cannot form
     * a valid E.164 number), the email is lower-cased, and {@code null} becomes the empty string.
     */
    public static String keyOf(String telephone, String email, String householdId) {
        String normalizedTelephone = OwnerTelephone.toE164(telephone);
        if (normalizedTelephone == null) {
            normalizedTelephone = telephone == null ? "" : telephone;
        }
        String normalizedEmail = email == null ? "" : email.toLowerCase(Locale.ROOT);
        String household = householdId == null ? "" : householdId;
        return normalizedTelephone + "|" + normalizedEmail + "|" + household;
    }
}

